  ( (c2 <> 46 /\ d_p d = -1 /\ d_xp d = false /\ d_t d = c2 /\ rest = s2b /\ conv_type c2 = Some (d_ty d))
  \/ (c2 = 46 /\ d_xp d = true /\ exists c3 s3b, s2b = c3 :: s3b /\ c3 <> 42 /\
      exists s3, getint s2b 0 = Some (d_p d, s3) /\ s3 = d_t d :: rest /\ conv_type (d_t d) = Some (d_ty d)) ).
